window.GuaData = window.GuaData || {}; window.GuaData.artwork = {"1":{"hexagramNumber":1,"typeKey":"ENTJ-calm-autonomous","title":"開途定向者","src":"./assets/personality/twobu/hexagram-01.webp","width":1254,"height":1254,"conceptZh":"先擬好遠方的路徑，也願意停下來等同行者；以高天空間表現乾的力量與節奏。","sha256":"9af2b4a1e623116768a720c1be33ee5b67c6a7a5f940e63d2a3e63a8e32e0f2a","derivativeVersion":"twobu-corners-v3"},"2":{"hexagramNumber":2,"typeKey":"ISFJ-calm-cooperative","title":"厚土共育者","src":"./assets/personality/twobu/hexagram-02.webp","width":1254,"height":1254,"conceptZh":"兩人先商量再共同移植幼苗，兩個同樣大小的水杯提醒照料也要包含自己；坤的厚土不是單向犧牲。","sha256":"0d6e7ea51be0ea545413048d2f433bdce7097531f4fe2de23be166b37d4c3668","derivativeVersion":"twobu-corners-v3"},"3":{"hexagramNumber":3,"typeKey":"ESTP-sensitive-autonomous","title":"雨中拓路者","src":"./assets/personality/twobu/hexagram-03.webp","width":1254,"height":1254,"conceptZh":"雨中只先鋪出第一小段路，旁邊的新芽呼應屯的初生；情緒鮮明仍可採用可回退的小試驗。","sha256":"59df69cb5bfc6135191b989bd4387ca444abc373250549e5db70837cc1900de2","derivativeVersion":"twobu-corners-v3"},"4":{"hexagramNumber":4,"typeKey":"INTP-sensitive-autonomous","title":"泉問探理者","src":"./assets/personality/twobu/hexagram-04.webp","width":1254,"height":1254,"conceptZh":"獨自在山泉旁以葉片做小實驗，把心中的好問題放回現場驗證；蒙代表學習而不是愚昧。","sha256":"dd6ee126e9af0b1d184964e6a9f1fe7949ab4335b99aec219e6789688f5045a5","derivativeVersion":"twobu-corners-v3"},"5":{"hexagramNumber":5,"typeKey":"ESTP-calm-autonomous","title":"候潮行動者","src":"./assets/personality/twobu/hexagram-05.webp","width":1254,"height":1254,"conceptZh":"先整理好船與工具，在岸邊觀察水勢；需的等待是一種準備，不是消極停滯。","sha256":"33601c6be2fbd1a510dbcad207f8d828d0f2d8a27b4a82f80aed891bd1d30f68","derivativeVersion":"twobu-corners-v3"},"6":{"hexagramNumber":6,"typeKey":"ESTJ-sensitive-autonomous","title":"明界議事者","src":"./assets/personality/twobu/hexagram-06.webp","width":1254,"height":1254,"conceptZh":"以不同水路與桌面邊界呈現規則和事實待澄清；訟不是好辯的標籤，而是先說清共同約定。","sha256":"d532398b4256b549ccd6b1e8428f2031855512df1c82f51750d83e392a3d60d5","derivativeVersion":"twobu-corners-v3"},"7":{"hexagramNumber":7,"typeKey":"ENTJ-calm-cooperative","title":"整隊共進者","src":"./assets/personality/twobu/hexagram-07.webp","width":1254,"height":1254,"conceptZh":"兩位同等位置的夥伴先對齊模組橋的接點；師的群體紀律轉成能共同承擔的步伐，避開軍事威權。","sha256":"493ddb5f2615972c186913794cd732b55a36b3523636b5e711ed34bd9aed2530","derivativeVersion":"twobu-corners-v3"},"8":{"hexagramNumber":8,"typeKey":"ESFJ-calm-cooperative","title":"結伴安居者","src":"./assets/personality/twobu/hexagram-08.webp","width":1254,"height":1254,"conceptZh":"共同討論庭院水路與座位，入口保持敞開；比的歸屬來自互相選擇，也容得下不同步調。","sha256":"1a4572ee7a57fc15184ddc15cfed7a7102c458583c6779fb1af0f2773da2964e","derivativeVersion":"twobu-corners-v3"},"9":{"hexagramNumber":9,"typeKey":"ESTP-calm-cooperative","title":"聚風蓄勢者","src":"./assets/personality/twobu/hexagram-09.webp","width":1254,"height":1254,"conceptZh":"共同製作小風車、保留已完成零件，在密雲下慢慢蓄勢；小畜以可留下的小成果支持大計畫。","sha256":"8de7a86935b404f9c0cd5be7109753ad7e7ea42f2a314a3456a83cdc11f7b25b","derivativeVersion":"twobu-corners-v3"},"10":{"hexagramNumber":10,"typeKey":"ESFJ-calm-autonomous","title":"知禮行路者","src":"./assets/personality/twobu/hexagram-10.webp","width":1254,"height":1254,"conceptZh":"獨自確認腳步與距離，在安睡的虎旁保留寬裕空間；履的分寸同時尊重他人與自己的界線。","sha256":"7d278197c2c6c0d248440d288cb047db08318e6ae2edf12ee8565913388cccfd","derivativeVersion":"twobu-corners-v3"},"11":{"hexagramNumber":11,"typeKey":"ESTJ-calm-cooperative","title":"通流築序者","src":"./assets/personality/twobu/hexagram-11.webp","width":1254,"height":1254,"conceptZh":"兩人疏通從不同高度而來的灌溉渠，讓資源雙向抵達；泰的順暢需要維護，而非永遠不變。","sha256":"727aa888521d168f58152016f34b2f881f4af8df7485f1e169326fbea89902ef","derivativeVersion":"twobu-corners-v3"},"12":{"hexagramNumber":12,"typeKey":"INFP-calm-autonomous","title":"守心候通者","src":"./assets/personality/twobu/hexagram-12.webp","width":1254,"height":1254,"conceptZh":"守住自己的安靜工作室，同時主動打開一扇小窗；否是暫時不通的情境，不是人格注定封閉。","sha256":"cbad0ab5da284502f94a72c0fbef3557112b9036286cd868eb14262bde043e21","derivativeVersion":"twobu-corners-v3"},"13":{"hexagramNumber":13,"typeKey":"ENFJ-calm-cooperative","title":"聚志同行者","src":"./assets/personality/twobu/hexagram-13.webp","width":1254,"height":1254,"conceptZh":"兩人帶著不同顏色的布，在原野共同縫成一面不必完全相同的帆；同人重視共同志向與差異。","sha256":"38859921a385f87a4ef634b66f6b35b10206df6bfc9c1238679057457d634218","derivativeVersion":"twobu-corners-v3"},"14":{"hexagramNumber":14,"typeKey":"ENTP-calm-cooperative","title":"集光開想者","src":"./assets/personality/twobu/hexagram-14.webp","width":1254,"height":1254,"conceptZh":"合作收集不同透鏡，也一起選出這次要用的少數組合；大有的豐富需要分享與取捨的容器。","sha256":"2f23519dce932fc4a272e02454b0dc8977eb7edfadca0846767de505db3b8c44","derivativeVersion":"twobu-corners-v3"},"15":{"hexagramNumber":15,"typeKey":"INFP-calm-cooperative","title":"留白共生者","src":"./assets/personality/twobu/hexagram-15.webp","width":1254,"height":1254,"conceptZh":"兩人在低矮山坡同高度工作，一位把自己的石子放進共同構圖；謙的留白不應變成消失。","sha256":"532e27a4195da0f6964d56d635c5ce03be7c3db6d1cfea39eed77dcde8bd0612","derivativeVersion":"twobu-corners-v3"},"16":{"hexagramNumber":16,"typeKey":"ESFP-calm-cooperative","title":"和樂鼓動者","src":"./assets/personality/twobu/hexagram-16.webp","width":1254,"height":1254,"conceptZh":"先一起確認節奏，再敲響小鼓；豫的歡樂包含準備與休息位置，沒有要求人人都熱烈回應。","sha256":"2de93d51c80ecd27bb7fe356d5fd05f723a3b38bbbf13e2b8420f67fe3d55e5d","derivativeVersion":"twobu-corners-v3"},"17":{"hexagramNumber":17,"typeKey":"ISFP-calm-cooperative","title":"隨時共作人","src":"./assets/personality/twobu/hexagram-17.webp","width":1254,"height":1254,"conceptZh":"兩位工作者共同調整織帶，各自保留不同顏色與轉向；隨是有判準地配合情境，而非盲從。","sha256":"c6596621a546a9a290d5a843f800b0cf8a725e4db7eddcaf50fd00f9ec64582e","derivativeVersion":"twobu-corners-v3"},"18":{"hexagramNumber":18,"typeKey":"INTJ-sensitive-cooperative","title":"修本更新者","src":"./assets/personality/twobu/hexagram-18.webp","width":1254,"height":1254,"conceptZh":"先共同查看水車真正卡住的根部，再更換磨損零件；蠱的更新兼顧承接者，不把舊物一概否定。","sha256":"d21b759f7b3aad39b6e977535d52633ded95bd567c8fb32dba4e29bd47caa888","derivativeVersion":"twobu-corners-v3"},"19":{"hexagramNumber":19,"typeKey":"ENFJ-calm-autonomous","title":"近人啟途者","src":"./assets/personality/twobu/hexagram-19.webp","width":1254,"height":1254,"conceptZh":"先準備好可調整的矮凳與園徑，仍以敞開手勢等候對方選擇；臨的靠近是一份尊重自主的邀請。","sha256":"c8b65165e9de8737b78d8e3ffc804b990dd3c14f209b09edbbeb6b9c69746e90","derivativeVersion":"twobu-corners-v3"},"20":{"hexagramNumber":20,"typeKey":"INFJ-calm-autonomous","title":"靜觀織意者","src":"./assets/personality/twobu/hexagram-20.webp","width":1254,"height":1254,"conceptZh":"從低平台觀察田野與葉影，再把透鏡放低回到現場；觀的洞見需要接受真實回應，不是神秘讀心。","sha256":"e97db876735e5eeb1eb7ddeef0a44de31ca391937ef65c826308d4071455c613","derivativeVersion":"twobu-corners-v3"},"21":{"hexagramNumber":21,"typeKey":"ENTP-sensitive-cooperative","title":"辨結通路者","src":"./assets/personality/twobu/hexagram-21.webp","width":1254,"height":1254,"conceptZh":"兩人先攤開卡住門道的繩結，再以合宜力度拆解；噬嗑的咬開阻隔轉成公平釐清，避開刑罰畫面。","sha256":"9362ca275817cfa69689ae38e4bdc713aed75fe343c533df51cbccf90bb38082","derivativeVersion":"twobu-corners-v3"},"22":{"hexagramNumber":22,"typeKey":"ISFP-sensitive-autonomous","title":"映心造境者","src":"./assets/personality/twobu/hexagram-22.webp","width":1254,"height":1254,"conceptZh":"獨自製作素器，以簡單布與枝葉襯托真實形狀；賁的美幫助表達，而不是遮住所有內心需要。","sha256":"84b231bfd8e1ff5b744d641e526f874d955ad6fe5e139835110eee59d5871a12","derivativeVersion":"twobu-corners-v3"},"23":{"hexagramNumber":23,"typeKey":"INTJ-sensitive-autonomous","title":"去蕪固本者","src":"./assets/personality/twobu/hexagram-23.webp","width":1254,"height":1254,"conceptZh":"從老舊棚架卸下失效枝條，保護仍能承重的根與柱；剝的減法指向穩固基礎，而不是一片荒敗。","sha256":"3e4c99165ebd6e6daa89eadd9357aa88b9202db5225eac716a7ab13d37b57491","derivativeVersion":"twobu-corners-v3"},"24":{"hexagramNumber":24,"typeKey":"ESFP-calm-autonomous","title":"返真再行者","src":"./assets/personality/twobu/hexagram-24.webp","width":1254,"height":1254,"conceptZh":"休息後沿熟悉小徑重新出發，腳邊新芽回應復的循環；回返建立在真正調整，不只是重複耗損。","sha256":"b2e6315a2d513e9dc27ca29fc320c506023b13966f0b7a51a496a68ac938e41a","derivativeVersion":"twobu-corners-v3"},"25":{"hexagramNumber":25,"typeKey":"ISTP-calm-autonomous","title":"本真試行者","src":"./assets/personality/twobu/hexagram-25.webp","width":1254,"height":1254,"conceptZh":"以簡單槓桿實測石塊重量，保留尚未確定的空間；無妄強調貼近事實，也承認偶然不能全被控制。","sha256":"63a6cb92870760b961b97f9cb1eec206b2781ef23329b7bcba8ad092e74a1f78","derivativeVersion":"twobu-corners-v3"},"26":{"hexagramNumber":26,"typeKey":"INTJ-calm-autonomous","title":"蓄識定局者","src":"./assets/personality/twobu/hexagram-26.webp","width":1254,"height":1254,"conceptZh":"從山中小書室帶著一件可試作模型走到外面；大畜的累積與節制，最後需要接受現實檢驗。","sha256":"8167bd45b10d88707f6aec3cc76bc99436593f875c33f37958fad1c4ccce8c3f","derivativeVersion":"twobu-corners-v3"},"27":{"hexagramNumber":27,"typeKey":"ISFJ-calm-autonomous","title":"養心守日者","src":"./assets/personality/twobu/hexagram-27.webp","width":1254,"height":1254,"conceptZh":"安排能持續維持的茶食日常，也替自己留下一杯；頤的滋養包含給出與接收，沒有性別角色分配。","sha256":"3e8f3f370b99c9b0e3212f28d4e29c0e37fc2119b5617c2cb921dc087ccedf8b","derivativeVersion":"twobu-corners-v3"},"28":{"hexagramNumber":28,"typeKey":"ISTP-sensitive-cooperative","title":"承重共構者","src":"./assets/personality/twobu/hexagram-28.webp","width":1254,"height":1254,"conceptZh":"兩位工作者共同為微彎的梁增添支點；大過不是證明誰撐得最多，而是重新分配負荷與資源。","sha256":"ff08036e2a8ead64269047ce4b5070b17c8a6ece7c162ac307d56759aeda6bb2","derivativeVersion":"twobu-corners-v3"},"29":{"hexagramNumber":29,"typeKey":"INFP-sensitive-autonomous","title":"深流守信者","src":"./assets/personality/twobu/hexagram-29.webp","width":1254,"height":1254,"conceptZh":"在深水旁只選第一個可行小步，岸上的繩索代表可尋求的支援；坎不是人格命運，而是練習穿越未知。","sha256":"b712d436717cca777109f5fd82e53e8ed7d0768c4e901b446114931b21ea43e2","derivativeVersion":"twobu-corners-v3"},"30":{"hexagramNumber":30,"typeKey":"ENFJ-sensitive-autonomous","title":"持光引路者","src":"./assets/personality/twobu/hexagram-30.webp","width":1254,"height":1254,"conceptZh":"先替手中的燈補充燃料，再照向可步行的路；離的持光需要真實支持，沒有永遠燃燒自己的要求。","sha256":"f4abedc98c3f722a76f08768ec3a682a675ba28bd6e2c42585e98511b4d71c95","derivativeVersion":"twobu-corners-v3"},"31":{"hexagramNumber":31,"typeKey":"INFP-sensitive-cooperative","title":"聽心相應者","src":"./assets/personality/twobu/hexagram-31.webp","width":1254,"height":1254,"conceptZh":"兩人隔著淺水碗安靜聆聽，保留各自清楚的空間；咸的感應需要詢問與確認，不用讀心或性別配對。","sha256":"0d314664086ad6e37439b057c6ad046f17295a964ecb9d31c8468ff64318ed5a","derivativeVersion":"twobu-corners-v3"},"32":{"hexagramNumber":32,"typeKey":"ISTJ-calm-autonomous","title":"守序長行者","src":"./assets/personality/twobu/hexagram-32.webp","width":1254,"height":1254,"conceptZh":"維護循環水輪，旁邊不同生長階段的植株提醒季節變化；恆的長久，是守方向也調整方法。","sha256":"36662a5ba68d58fe94ac341a9a0f6127103beacf4b47e75c72f324b4c33cd91b","derivativeVersion":"twobu-corners-v3"},"33":{"hexagramNumber":33,"typeKey":"ISFP-calm-autonomous","title":"留白守山人","src":"./assets/personality/twobu/hexagram-33.webp","width":1254,"height":1254,"conceptZh":"山腳的創作者將自己的工作角落留出通風與遠景，折起屏風但不封閉通路。以遯的天山距離表現有意識的界線，保留日後重返交流的入口。","sha256":"7966c6451673f829c83e4791306630ccb1c378de905a4bcec1323f34620246fb","derivativeVersion":"twobu-corners-v3"},"34":{"hexagramNumber":34,"typeKey":"ESTJ-calm-autonomous","title":"有度推進者","src":"./assets/personality/twobu/hexagram-34.webp","width":1254,"height":1254,"conceptZh":"執行者把力量接到有邊界的木製推進裝置，手掌主動停在閘門前核對，遠處雷雲只是動勢。強勁與節制同時成立。","sha256":"a4adb5650498bf018dd50ebcee9fd22a5c02fea29e16fe731a9aabfaa1b6777d","derivativeVersion":"twobu-corners-v3"},"35":{"hexagramNumber":35,"typeKey":"ESTP-sensitive-cooperative","title":"共行見曉者","src":"./assets/personality/twobu/hexagram-35.webp","width":1254,"height":1254,"conceptZh":"兩位夥伴一起完成面向晨光的低平台，同時回顧固定支撐與實作成果。以地上出明連結現場應變與共享貢獻。","sha256":"19b7d3e3da61005f50c9a57e59769d128d59520d653c7b4a278d3f81fdfdcbdd","derivativeVersion":"twobu-corners-v3"},"36":{"hexagramNumber":36,"typeKey":"INFJ-sensitive-autonomous","title":"藏光護念者","src":"./assets/personality/twobu/hexagram-36.webp","width":1254,"height":1254,"conceptZh":"創作者在土色拱廊下保護小燈，另一端的開口讓光有安全的出口。以明入地中表現信念的保存與選擇表達時機，避免受難或被囚意象。","sha256":"725c46832ceae9cefdea8ec6775a3d9c462f783b9e1437a6996b78a4d9da69a2","derivativeVersion":"twobu-corners-v3"},"37":{"hexagramNumber":37,"typeKey":"ISTJ-calm-cooperative","title":"共築日常者","src":"./assets/personality/twobu/hexagram-37.webp","width":1254,"height":1254,"conceptZh":"兩位夥伴在日常共用桌前調整可拆換的木格與器物位置，風從小火爐上方的開窗流過。以共同協商維持可靠日常，不指定家庭或性別角色。","sha256":"8e2aada75087dc4c843f6c5d853e4b2a22ff4ef20dfca77c9b65c9fe8fcd6a0f","derivativeVersion":"twobu-corners-v3"},"38":{"hexagramNumber":38,"typeKey":"ENTP-calm-autonomous","title":"異路探問者","src":"./assets/personality/twobu/hexagram-38.webp","width":1254,"height":1254,"conceptZh":"探問者在上方暖光與下方水澤之間測試兩種不同小橋，讓不同路徑仍接到共同的平台。以睽表現差異中的小尺度驗證。","sha256":"7500ed4b15326a09b33608b386c881eb819f7c1de7967959ffd888476c13a021","derivativeVersion":"twobu-corners-v3"},"39":{"hexagramNumber":39,"typeKey":"ISTJ-sensitive-cooperative","title":"聯手越嶺者","src":"./assets/personality/twobu/hexagram-39.webp","width":1254,"height":1254,"conceptZh":"兩位行者面對山前積水，一起查看安全落腳點並握持同一條鬆繩。停下核對與接受支援，是共同越嶺的實際能力。","sha256":"a90581f26fe297e0a4e1d968eb03d1abcd5279cb1e8533ddf8cc65dac7d6dc7b","derivativeVersion":"twobu-corners-v3"},"40":{"hexagramNumber":40,"typeKey":"ISTP-calm-cooperative","title":"解結共修者","src":"./assets/personality/twobu/hexagram-40.webp","width":1254,"height":1254,"conceptZh":"兩位修理者先交換看法，再解開卡住水輪的繩結。雨後水道重新流動，連結解卦的鬆動與可使用的實際解法。","sha256":"3902e10a25ad64509e9bbfb050625b16feb2cdc256c3496eef05a5e9dc666593","derivativeVersion":"twobu-corners-v3"},"41":{"hexagramNumber":41,"typeKey":"ISFJ-sensitive-cooperative","title":"知量共養者","src":"./assets/personality/twobu/hexagram-41.webp","width":1254,"height":1254,"conceptZh":"照料者與夥伴共同衡量有限的水，留下自己休息用的一杯而非全部倒出。以山下有澤與適量滋養表現界線及平等分工。","sha256":"71f2889b9e0db23ed4eba18edb413c14a48c149f8c5fdf4817dd1776ed0526f7","derivativeVersion":"twobu-corners-v3"},"42":{"hexagramNumber":42,"typeKey":"ENFJ-sensitive-cooperative","title":"互益引路者","src":"./assets/personality/twobu/hexagram-42.webp","width":1254,"height":1254,"conceptZh":"兩位共同培育者把小水渠分向不同高度的苗木，各自調整而非強迫同步成長。以風雷的動能表現支持流動與共同受益。","sha256":"d0b98fd57fdb0eda17dda2cc067889141ed1c76f52338a75ebfaf119218852b7","derivativeVersion":"twobu-corners-v3"},"43":{"hexagramNumber":43,"typeKey":"ENTJ-sensitive-autonomous","title":"明言開路者","src":"./assets/personality/twobu/hexagram-43.webp","width":1254,"height":1254,"conceptZh":"發起者把已有的方案放上開放的平台，手勢留出回應的方向；上方水澤意象保留在雲與水盆中。果斷伴隨公開理由與可回應的空間。","sha256":"459bcda88285b221f1d6b4c903f694e6243e1458aa0fda0ba6eb6061471c1683","derivativeVersion":"twobu-corners-v3"},"44":{"hexagramNumber":44,"typeKey":"ENFP-sensitive-autonomous","title":"遇風尋路者","src":"./assets/personality/twobu/hexagram-44.webp","width":1254,"height":1254,"conceptZh":"探索者在半開門前接住風送來的種莢，另一手仍握著門緣調整開度。姤的相遇帶來想像，也保有選擇承諾的自主節奏。","sha256":"b87a3f9317e9c0880f97e6a0c8b78a2f0888029793ee16e42f27ad3dd3319ebc","derivativeVersion":"twobu-corners-v3"},"45":{"hexagramNumber":45,"typeKey":"ESFJ-sensitive-cooperative","title":"聚心成席者","src":"./assets/personality/twobu/hexagram-45.webp","width":1254,"height":1254,"conceptZh":"兩位籌備者把座席圍成開口的圓，保留可自由加入或離開的位置。澤上於地的聚集意象，轉成容納不同聲音的共同場合。","sha256":"b3c99b306c8f930b9eb446bd7032158c205af82bab94d2f52c3951bfc4458735","derivativeVersion":"twobu-corners-v3"},"46":{"hexagramNumber":46,"typeKey":"ENFP-calm-cooperative","title":"共栽新枝者","src":"./assets/personality/twobu/hexagram-46.webp","width":1254,"height":1254,"conceptZh":"兩位夥伴共同把幼木安置到土中，支架可以調整，枝條向上留有空間。升的地中生木成為耐心陪伴、持續照料的原創比喻。","sha256":"fc2969bc8b5919142692a891dbc08e6e97c471eba7fd6105970b29d5c408154d","derivativeVersion":"twobu-corners-v3"},"47":{"hexagramNumber":47,"typeKey":"ISTP-sensitive-autonomous","title":"限中尋徑者","src":"./assets/personality/twobu/hexagram-47.webp","width":1254,"height":1254,"conceptZh":"受限的修理者在乾淺水池旁試做竹管，取用眼前有限材料並把開口朝外，讓限制可被看見、協助有入口。困不作命運或失敗標籤。","sha256":"48e21f5cd73569ed15a52538364789ca425458a311bb8fad79b19fd7d250e66d","derivativeVersion":"twobu-corners-v3"},"48":{"hexagramNumber":48,"typeKey":"INTP-calm-cooperative","title":"共汲知泉者","src":"./assets/personality/twobu/hexagram-48.webp","width":1254,"height":1254,"conceptZh":"兩位思考者把井水汲入形狀不同、皆可使用的容器，順便調整井口高度。知識的深度須透過可理解的入口成為共同資源。","sha256":"3715fd2b96628eae2ac2fb762350448ccb46e3913def09692137236935c340ea","derivativeVersion":"twobu-corners-v3"},"49":{"hexagramNumber":49,"typeKey":"ENTJ-sensitive-cooperative","title":"共議革新者","src":"./assets/personality/twobu/hexagram-49.webp","width":1254,"height":1254,"conceptZh":"兩位改革者把磨損結構拆成可重組的木件，邊比較舊件與新接點邊共同定案。以革表現時機、信任與受影響者參與的更新。","sha256":"eecff5ab0ff51324d62a93e18a4e54e285aff607943397df18d45f21931ee9a7","derivativeVersion":"twobu-corners-v3"},"50":{"hexagramNumber":50,"typeKey":"INTJ-calm-cooperative","title":"共煉新器者","src":"./assets/personality/twobu/hexagram-50.webp","width":1254,"height":1254,"conceptZh":"兩位設計者一同檢查原創三足器的把手與受力，材料在適度熱源中轉成共享滋養。鼎是能維護、能使用的共同系統，非照摹任何館藏器物。","sha256":"b8c400a67533a9aae5f1d9fb317f29171a7c5588cb929e7686d49ca69f6535fe","derivativeVersion":"twobu-corners-v3"},"51":{"hexagramNumber":51,"typeKey":"ENTP-sensitive-autonomous","title":"驚中試新者","src":"./assets/personality/twobu/hexagram-51.webp","width":1254,"height":1254,"conceptZh":"突發雷聲使探索者暫停手上的小原型，先以簡單實物確認新想法。震的驚動與好奇並存，但畫面保留核對事實的短暫停頓。","sha256":"cbd6cb71fbbaf3ff133d0b4155ac227ebc93d1be91f89ecaaca44a6b45b8b014","derivativeVersion":"twobu-corners-v3"},"52":{"hexagramNumber":52,"typeKey":"INTP-calm-autonomous","title":"止處深思者","src":"./assets/personality/twobu/hexagram-52.webp","width":1254,"height":1254,"conceptZh":"獨處思考者在雙重山勢前把問題縮到一盤幾何木件，空出一塊待測位置。艮的止處提供可站穩的範圍，旁邊的小徑仍朝外延伸。","sha256":"e60c5fa87253b316f5dbbab501d09ee2b7e7910b098f8b68f079c48007f95870","derivativeVersion":"twobu-corners-v3"},"53":{"hexagramNumber":53,"typeKey":"INFJ-calm-cooperative","title":"同行漸成者","src":"./assets/personality/twobu/hexagram-53.webp","width":1254,"height":1254,"conceptZh":"兩位同行者在山坡幼樹旁，把可移動小踏步調到共同可走的間距。漸的山上有木連結長期願景、耐心與看得見的階段。","sha256":"95c30402c0dc90851956dab79f2f8626b640b91d686b7a4e841e70717fb05133","derivativeVersion":"twobu-corners-v3"},"54":{"hexagramNumber":54,"typeKey":"ESFJ-sensitive-autonomous","title":"擇約守心者","src":"./assets/personality/twobu/hexagram-54.webp","width":1254,"height":1254,"conceptZh":"主動照顧者在湖畔整理自己的座席與空白邀請物件，保留可選擇的入口。以歸妹檢視關係位置的課題，轉成平等同意與加入前的自我確認。","sha256":"ec82db5ead1c0bd8cc2fe018a2764aa52db78aa56832e01af1fab072c347e0c5","derivativeVersion":"twobu-corners-v3"},"55":{"hexagramNumber":55,"typeKey":"ESFP-sensitive-autonomous","title":"盛時點光者","src":"./assets/personality/twobu/hexagram-55.webp","width":1254,"height":1254,"conceptZh":"表達者把豐盛的當下化為一盞自己完成的紙燈，桌旁留一張休息凳和收納盒。雷電皆至的飽滿轉成精彩與收尾並存的日常場景。","sha256":"1416da2c7930d60c9f958832f2b52ee7d467bd8c83d7ac2ce29c0b6a45c42236","derivativeVersion":"twobu-corners-v3"},"56":{"hexagramNumber":56,"typeKey":"ENFP-calm-autonomous","title":"行旅拾意者","src":"./assets/personality/twobu/hexagram-56.webp","width":1254,"height":1254,"conceptZh":"旅人停在陌生山路上的開放驛亭，先整理行囊、觀察所在環境再選路。小火光照亮可返回的小徑，表現自由與連結共存。","sha256":"a4cd09c9f27ffb46ffc4cb8b98081e44234ffc773abec158c59dbde8ae1a4bb6","derivativeVersion":"twobu-corners-v3"},"57":{"hexagramNumber":57,"typeKey":"ISFP-sensitive-cooperative","title":"柔風共作人","src":"./assets/personality/twobu/hexagram-57.webp","width":1254,"height":1254,"conceptZh":"兩位創作者在柔風吹動的布幔旁共修一件作品，一方示意自己的選色，另一方調整材料。風的漸入日常包含互相聽見，而非單方順從。","sha256":"565ef042ed9bde69a34e1eef4edb008295b625a73d02e1390ab9934dbf93267a","derivativeVersion":"twobu-corners-v3"},"58":{"hexagramNumber":58,"typeKey":"ESFP-sensitive-cooperative","title":"歡語共學者","src":"./assets/personality/twobu/hexagram-58.webp","width":1254,"height":1254,"conceptZh":"兩位朋友在相連水澤旁分享小型手作體驗，一張空凳也歡迎安靜參與。兌的喜悅與共學保留真誠差異，不要求每個人表情一致。","sha256":"d3ec8e0a4c105c548cbd92e5dfd2690b58cb02c81951afb5eaf9cba69ad9871e","derivativeVersion":"twobu-corners-v3"},"59":{"hexagramNumber":59,"typeKey":"ENFP-sensitive-cooperative","title":"散結連橋者","src":"./assets/personality/twobu/hexagram-59.webp","width":1254,"height":1254,"conceptZh":"兩位連結者在水邊把散開的繩索重新接成鬆而可靠的小橋，留下各自岸邊的空間。風行水上的渙，轉為釐清隔閡與自由連結。","sha256":"a706aea573aca4c3c188234c2fab71247094514b6a6fa56dd3301392797319ff","derivativeVersion":"twobu-corners-v3"},"60":{"hexagramNumber":60,"typeKey":"ISTJ-sensitive-autonomous","title":"定度守衡者","src":"./assets/personality/twobu/hexagram-60.webp","width":1254,"height":1254,"conceptZh":"規劃者為湖邊水槽調整可拆換的木製水閘，保留一個溢流出口。節的尺度服務生活，規則可隨條件改變而重新衡量。","sha256":"c48d31f1cedff19ba8ee0503e814d0f45c4ed49d281f0325943a199cdfcc3cb8","derivativeVersion":"twobu-corners-v3"},"61":{"hexagramNumber":61,"typeKey":"INFJ-sensitive-cooperative","title":"誠聲相和者","src":"./assets/personality/twobu/hexagram-61.webp","width":1254,"height":1254,"conceptZh":"兩位對話者在有風的水邊，各自把一塊透明器物放到同一個可見位置，確認彼此所指。遠處一對水鳥呼應，真誠透過可核對的表達建立信任。","sha256":"ef939470df8dd4e454d72ead57285498b8307bbe61e11ffd7eaeb6df0d6fa686","derivativeVersion":"twobu-corners-v3"},"62":{"hexagramNumber":62,"typeKey":"ISFJ-sensitive-autonomous","title":"細步護行者","src":"./assets/personality/twobu/hexagram-62.webp","width":1254,"height":1254,"conceptZh":"照料者在低矮山徑邊先修一級容易踩空的小踏步，再查看自己剩餘材料。低飛小鳥呼應小過的小步與適度，不把周到畫成無限責任。","sha256":"5b38cba69a244838badebc87f1bcd2802ef9268324996c9f208cb04eb7cd81f1","derivativeVersion":"twobu-corners-v3"},"63":{"hexagramNumber":63,"typeKey":"ESTJ-sensitive-cooperative","title":"共守成局者","src":"./assets/personality/twobu/hexagram-63.webp","width":1254,"height":1254,"conceptZh":"兩位維護者在已可使用的茶水裝置旁核對接點與交接，水在有節制的小火上方。既濟的完成是一個需要共同照料的階段。","sha256":"4d3dda8e64468b98ff3a8653661cd8d4c053ed8c987c858388d2777c956ec7d8","derivativeVersion":"twobu-corners-v3"},"64":{"hexagramNumber":64,"typeKey":"INTP-sensitive-cooperative","title":"共辨未來者","src":"./assets/personality/twobu/hexagram-64.webp","width":1254,"height":1254,"conceptZh":"兩位探索者在尚未接上的水上小橋前，先把可用與待測木件分置兩盤，準備下一個可驗證落腳點。未濟的開放性有清楚界線與共同實作。","sha256":"fa17be35180f0ce5512d9ccf918e76e72d74abb2a24a5c367fa241b9cb3cc7c0","derivativeVersion":"twobu-corners-v3"}};
